int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int n;
    scanf("%d", &n);

    int *a = malloc(n * sizeof(int));
    int *b = malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int i = 0; i < n; i++) scanf("%d", &b[i]);

    int ans = 0;

    for (int k = 0; k < 29; k++) {
        int mod = 1 << (k + 1);
        int *b_mod = malloc(n * sizeof(int));
        for (int i = 0; i < n; i++) {
            b_mod[i] = b[i] & (mod - 1);
        }
        qsort(b_mod, n, sizeof(int), cmp);

        long long count = 0;
        int threshold = 1 << k;

        for (int i = 0; i < n; i++) {
            int a_mod = a[i] & (mod - 1);

            // range [threshold, 2*threshold - 1]
            int l1 = threshold - a_mod;
            int r1 = 2*threshold - 1 - a_mod;
            // range [3*threshold, 4*threshold - 2]
            int l2 = 3*threshold - a_mod;
            int r2 = 4*threshold - 2 - a_mod;

            // count in [l1, r1] within [0, mod-1]
            if (l1 < 0) {
                l1 += mod;
                r1 += mod;
            }
            if (r1 >= mod) {
                // split
                int *left = (int*)bsearch(&l1, b_mod, n, sizeof(int), cmp);
                int *right = (int*)bsearch(&(int){mod}, b_mod, n, sizeof(int), cmp);
                int idx_l = left ? (left - b_mod) : (int)((int*)(bsearch(&l1, b_mod, n, sizeof(int), cmp)) - b_mod);
                // simpler: use pointer arithmetic
                int *p1 = (int*)bsearch(&l1, b_mod, n, sizeof(int), cmp);
                int *p2 = (int*)bsearch(&(int){mod}, b_mod, n, sizeof(int), cmp);
                if (!p1) {
                    int pos = 0;
                    while (pos < n && b_mod[pos] < l1) pos++;
                    p1 = &b_mod[pos];
                }
                if (!p2) p2 = b_mod + n;
                count += (p2 - p1);

                l1 = 0;
                r1 = r1 - mod;
            }
            {
                int *p1 = (int*)bsearch(&l1, b_mod, n, sizeof(int), cmp);
                int *p2 = (int*)bsearch(&(int){r1+1}, b_mod, n, sizeof(int), cmp);
                if (!p1) {
                    int pos = 0;
                    while (pos < n && b_mod[pos] < l1) pos++;
                    p1 = &b_mod[pos];
                }
                if (!p2) p2 = b_mod + n;
                count += (p2 - p1);
            }

            // second range
            if (l2 < 0) {
                l2 += mod;
                r2 += mod;
            }
            if (r2 >= mod) {
                int *p1 = (int*)bsearch(&l2, b_mod, n, sizeof(int), cmp);
                int *p2 = (int*)bsearch(&(int){mod}, b_mod, n, sizeof(int), cmp);
                if (!p1) {
                    int pos = 0;
                    while (pos < n && b_mod[pos] < l2) pos++;
                    p1 = &b_mod[pos];
                }
                if (!p2) p2 = b_mod + n;
                count += (p2 - p1);

                l2 = 0;
                r2 = r2 - mod;
            }
            {
                int *p1 = (int*)bsearch(&l2, b_mod, n, sizeof(int), cmp);
                int *p2 = (int*)bsearch(&(int){r2+1}, b_mod, n, sizeof(int), cmp);
                if (!p1) {
                    int pos = 0;
                    while (pos < n && b_mod[pos] < l2) pos++;
                    p1 = &b_mod[pos];
                }
                if (!p2) p2 = b_mod + n;
                count += (p2 - p1);
            }
        }

        if (count & 1) {
            ans |= (1 << k);
        }
        free(b_mod);
    }

    printf("%d\n", ans);

    free(a);
    free(b);
    return 0;
}

