int cmp(const void *x, const void *y) {
    long long a = *(long long*)x, b = *(long long*)y;
    return (a > b) - (a < b);
}

long long countInRange(long long *sorted, int n, long long lo, long long hi) {
    if (lo >= hi) return 0;
    // count elements in [lo, hi)
    long long *p = sorted;
    int l = 0, r = n;
    while (l < r) { int m = (l+r)/2; if (sorted[m] < lo) l=m+1; else r=m; }
    int left = l;
    l = 0; r = n;
    while (l < r) { int m = (l+r)/2; if (sorted[m] < hi) l=m+1; else r=m; }
    return l - left;
}

