        sort(bmod.begin(), bmod.end());

        long long cnt = 0;
        for(int i = 0; i < n; i++){
            long long ai = a[i] % mod;
            // need bmod[j] in [half - ai, mod - ai) mod mod
            long long lo = (half - ai % mod + mod) % mod;
            long long hi = (mod - ai % mod + mod) % mod; // = mod - ai if ai>0, else 0
            // hi = mod - ai mod mod
            // Count bmod in [lo, hi) cyclically
            if(lo < hi){
                cnt += lower_bound(bmod.begin(), bmod.end(), hi) - lower_bound(bmod.begin(), bmod.end(), lo);
            } else if(lo > hi){
                cnt += lower_bound(bmod.begin(), bmod.end(), (long long)mod) - lower_bound(bmod.begin(), bmod.end(), lo);
                cnt += lower_bound(bmod.begin(), bmod.end(), hi) - bmod.begin();
            }
            // if lo == hi, count is 0
        }
        if(cnt % 2 == 1) ans |= half;
    }

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N), b(N);
    for (int i = 0; i < N; ++i) cin >> a[i];
    for (int i = 0; i < N; ++i) cin >> b[i];

    long long ans = 0;

    // Compute each bit independently.
    // For bit k, only lower (k+1) bits matter.
    for (int k = 0; k < 29; ++k) {
        long long T = 1LL << k;
        long long MOD = 2LL << k; // 2^(k+1)

        vector<long long> bb(N);
        for (int i = 0; i < N; ++i) bb[i] = b[i] % MOD;
        sort(bb.begin(), bb.end());

        long long cnt = 0; // number of pairs with k-th bit = 1

        for (int i = 0; i < N; ++i) {
            long long x = a[i] % MOD;

            // Need count of y such that x+y in [T, 2T) or [3T, 4T)
            // modulo 2^(k+1), but since x,y in [0,2T), sum in [0,4T)
            auto count_range = [&](long long L, long long R) -> long long {
                return lower_bound(bb.begin(), bb.end(), R) - lower_bound(bb.begin(), bb.end(), L);
            };

            cnt += count_range(T - x, 2 * T - x);
            cnt += count_range(3 * T - x, 4 * T - x);
        }

        if (cnt % 2) ans |= T;
    }

    cout << ans << '\n';
    return 0;
}

