public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int[] a = new int[n];
        int[] b = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) b[i] = Integer.parseInt(st.nextToken());

        int ans = 0;
        for (int bit = 0; bit < 29; bit++) {
            int mask = (1 << (bit + 1)) - 1;
            int[] bb = new int[n];
            for (int i = 0; i < n; i++) {
                bb[i] = b[i] & mask;
            }
            Arrays.sort(bb);

            long count = 0;
            int threshold = 1 << bit;
            int nextThreshold = 1 << (bit + 1);
            for (int val : a) {
                int x = val & mask;
                // Count sums where bit is 1:
                // In range [threshold - x, nextThreshold - 1 - x] and [nextThreshold + threshold - x, nextThreshold*2 - 1 - x]
                int L1 = threshold - x;
                int R1 = nextThreshold - 1 - x;
                int L2 = nextThreshold + threshold - x;
                int R2 = (nextThreshold << 1) - 1 - x;

                count += upperBound(bb, R1) - lowerBound(bb, L1);
                count += upperBound(bb, R2) - lowerBound(bb, L2);
            }
            if ((count & 1) == 1) {
                ans |= (1 << bit);
            }
        }
        System.out.println(ans);
    }

    static int lowerBound(int[] arr, int key) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] arr, int key) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] <= key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

