public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        long[] a = new long[N], b = new long[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) a[i] = Long.parseLong(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) b[i] = Long.parseLong(st.nextToken());

        long ans = 0;
        for (int k = 0; k < 60; k++) {
            long mod = 1L << (k + 1);
            long[] r = new long[N], s = new long[N];
            for (int i = 0; i < N; i++) { r[i] = a[i] % mod; s[i] = b[i] % mod; }
            Arrays.sort(s);
            long count = 0;
            long L1 = 1L << k, R1 = 1L << (k+1), L2 = 3L << k, R2 = 1L << (k+2);
            for (int i = 0; i < N; i++) {
                // count s[j] in [L1-r[i], R1-r[i]) and [L2-r[i], R2-r[i]), intersected with [0, mod)
                count += countInRange(s, Math.max(0, L1-r[i]), Math.min(mod, R1-r[i]));
                count += countInRange(s, Math.max(0, L2-r[i]), Math.min(mod, R2-r[i]));
            }
            if ((count & 1) == 1) ans |= (1L << k);
        }
        System.out.println(ans);
    }

    static long countInRange(long[] s, long lo, long hi) {
        if (lo >= hi) return 0;
        int left = lowerBound(s, lo), right = lowerBound(s, hi);
        return right - left;
    }
    static int lowerBound(long[] s, long val) {
        int lo = 0, hi = s.length;
        while (lo < hi) { int mid = (lo+hi)/2; if (s[mid] < val) lo = mid+1; else hi = mid; }
        return lo;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int[] a = new int[N];
        int[] b = new int[N];

        for (int i = 0; i < N; i++) a[i] = fs.nextInt();
        for (int i = 0; i < N; i++) b[i] = fs.nextInt();

        int answer = 0;

        // Compute each bit independently.
        // For bit k, count pairs (i, j) such that the k-th bit of a[i] + b[j] is 1.
        // Only lower k+1 bits matter, so reduce modulo 2^(k+1).
        for (int k = 0; k < 29; k++) {
            int T = 1 << k;
            int MOD = T << 1; // 2^(k+1)

            int[] bb = new int[N];
            for (int i = 0; i < N; i++) bb[i] = b[i] & (MOD - 1);
            Arrays.sort(bb);

            long parity = 0; // only parity matters

            for (int i = 0; i < N; i++) {
                int x = a[i] & (MOD - 1);

                // Need count of y such that x + y is in [T, 2T) or [3T, 4T)
                // modulo actual integer sum range [0, 4T-2], but y < 2T and x < 2T,
                // so only intervals [T,2T) and [3T,4T) matter.
                parity ^= (countInRange(bb, T - x, 2 * T - x)
                        + countInRange(bb, 3 * T - x, 4 * T - x)) & 1L;
            }

            if ((parity & 1L) != 0) answer |= T;
        }

        System.out.println(answer);
    }

    // count of elements v in sorted arr with l <= v < r
    static int countInRange(int[] arr, int l, int r) {
        return lowerBound(arr, r) - lowerBound(arr, l);
    }

    static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}
